// Brain of titan-woodpecker: picks what the darts fly at, lets the rack go in one long stream, and then lets each bay's
// dart go as it is built. It runs on the main core while the pod stands on the base, and again on the base's own core
// once the pod has left (the same file).
// - Target: the heaviest robot on the other side the radars track that has a live core; once picked it is kept while
//   seen. Its point is its core (`contacts[].pos`), so every dart lands on the same spot, one after another, each
//   blast digging where the last one stopped.
// - Hidden target: with nothing tracked, darts fly to where it was last seen, or to the point across the arena from
//   where this titan started (the other side starts at -x of it), each at another height, and arm near that point.
// - Order: the rack's darts go nearest the enemy first, one every `gap` ticks, so no dart flies over one that is about
//   to leave, and they arrive spaced out (a dart caught in the blast ahead of it would be wasted).
const gap = param('gap', 2, { min: 1, max: 60 }); // ticks between two darts leaving the rack
const bayGap = param('bayGap', 4, { min: 1, max: 120 }); // ticks between two bays letting go
const minMass = param('minMass', 120, { min: 0, max: 100000 }); // kg: lighter robots are not the titan
const rescan = param('rescan', 180, { min: 30, max: 6000 }); // ticks between two looks at the target's size
const memory = param('memory', 15, { min: 0, max: 240 }); // s a last sighting is flown at before the start point is

function setup() {
  state.mirrorX = -self.pos.x;
  state.grips = [];
  state.bays = [];
  for (const p of parts) {
    if (p.type === 'decoupler') {
      const tag = p.tags.find((t) => /^g\d+$/.test(t));
      if (tag) state.grips.push({ n: Number(tag.slice(1)), x: p.pos.x });
    } else if (p.type === 'fabbay') {
      const tag = p.tags.find((t) => /^b\d+x$/.test(t));
      if (tag) state.bays.push(tag);
    }
  }
  // Nearest the enemy first.
  const toward = state.mirrorX;
  state.grips.sort((a, b) => Math.abs(a.x - toward) - Math.abs(b.x - toward) || a.n - b.n);
  state.next = 0;
  state.lastFire = -1000;
  state.lastBay = -1000;
  state.tid = -1;
  state.box = { l: 40, r: 40, d: 20, u: 20 };
  state.boxAt = -100000;
  state.last = null;
  state.shots = 0;
}

function pick() {
  let best = null;
  for (const c of contacts) {
    if (c.side !== 'enemy' || !c.core) continue;
    if (c.id === state.tid) return c;
    if (!best || c.mass > best.mass) best = c;
  }
  if (best && best.mass < minMass && state.last && time - state.last.at < memory) return null;
  return best;
}

function measure(t) {
  if (frame - state.boxAt < rescan) return;
  state.boxAt = frame;
  const ps = scan(t.id);
  if (!ps || ps.length === 0) return;
  let l = 0;
  let r = 0;
  let d = 0;
  let u = 0;
  for (const p of ps) {
    const ex = p.pos.x - t.pos.x;
    const ey = p.pos.y - t.pos.y;
    if (-ex > l) l = -ex;
    if (ex > r) r = ex;
    if (-ey > d) d = -ey;
    if (ey > u) u = ey;
  }
  state.box = { l, r, d, u };
}

function message() {
  const t = pick();
  state.shots++;
  if (t) {
    if (t.id !== state.tid) {
      state.tid = t.id;
      state.boxAt = -100000;
    }
    measure(t);
    state.last = { x: t.pos.x, y: t.pos.y, vx: t.vel.x, vy: t.vel.y, at: time };
    const b = state.box;
    // Wider than tall: thin from above, so the darts come down on it.
    const top = b.l + b.r > 1.5 * (b.d + b.u) ? 1 : 0;
    return { x: t.pos.x, y: t.pos.y, vx: t.vel.x, vy: t.vel.y, id: t.id, l: b.l, r: b.r, d: b.d, u: b.u, top };
  }
  const s = state.last;
  if (s && time - s.at < memory) {
    const age = Math.min(time - s.at, 4);
    return { x: s.x + s.vx * age, y: s.y + s.vy * age, vx: 0, vy: 0, id: -1, l: 60, r: 60, d: 40, u: 40, blind: 1 };
  }
  // Never seen: the point across the arena, low for every second dart (a ground titan), the rest at stepped heights.
  const y = state.shots % 2 === 0 ? 3 : 8 + ((state.shots * 29) % 145);
  return { x: state.mirrorX, y, vx: 0, vy: 0, id: -1, l: 80, r: 80, d: 10, u: 10, blind: 1 };
}

function tick() {
  if (state.grips.length === 0 && state.bays.length === 0) return;
  // The rack.
  if (state.next < state.grips.length && frame - state.lastFire >= gap && frame >= 2) {
    const grip = state.grips[state.next++];
    state.lastFire = frame;
    if (get('g' + grip.n, 'armed') > 0) {
      send('d' + grip.n, message());
      set('g' + grip.n, 'fire', 1);
    }
  }
  // The bays.
  if (frame - state.lastBay < bayGap) return;
  for (const tag of state.bays) {
    if (!(get(tag, 'ready') > 0)) continue;
    send(tag + get(tag, 'built'), message());
    set(tag, 'release', 1);
    state.lastBay = frame;
    return;
  }
}

// Guide of every titan-woodpecker dart (the ones standing on the rack and the ones the bays build). Lean on purpose:
// hundreds fly at once, so it never loops over parts and keeps its seeker off until the end.
// - setup() reads the base's message: the target's point and speed, its id, and how far its parts reach from its core
//   (l, r, d, u, so the dart knows where the target's edge is). With no message it stays a dud and flies up and away.
// - It climbs `climb` m straight up, then steers its speed onto the line to where the target will be: it pushes along
//   the line, cancels its speed across the line (no harder than `acrossMax`), and holds itself up against gravity.
// - `top` in the message (a target wider than it is tall): it flies level `over` m above the target and then down
//   to it at a slope of `loft`, so it lands on the roof at a slant: a wide base is thin from above.
// - It ends itself when it is spent (`life` s, or nearly out of energy) or has flown past its point.
// - Within `look` m of the point it switches its seeker on. If it sees the robot it was sent at, it takes that
//   robot's point and speed from then on. A flare or a robot too far from the point is ignored (`trust` m).
// - It arms its heads only within `armDist` m of the target's edge, so a shell that finds it on the way only breaks it.
const climb = param('climb', 9, { min: 0, max: 100 }); // m straight up before it turns
const look = param('look', 280, { min: 0, max: 300 }); // m from the point where the seeker goes on
const trust = param('trust', 60, { min: 1, max: 500 }); // m: a sighting further than this from the expected point is not believed
const armDist = param('armDist', 30, { min: 1, max: 300 }); // m from the target's edge where the heads arm
const kp = param('kp', 4, { min: 0, max: 50 });
const kd = param('kd', 1.3, { min: 0, max: 50 });
const push = param('push', 30, { min: 1, max: 200 }); // m/s^2 it asks for along the line
const across = param('across', 3, { min: 0, max: 20 }); // 1/s: how hard it cancels speed across the line
const acrossMax = param('acrossMax', 40, { min: 0, max: 200 }); // m/s^2 at most across the line
const over = param('over', 130, { min: 0, max: 240 }); // m above a wide target it aims at most
const loft = param('loft', 0.45, { min: 0, max: 2 }); // m of aim height per m of ground still to cover
const ahead = param('ahead', 1.2, { min: 0.1, max: 5 }); // s of flight it looks ahead along its path
const life = param('life', 12.5, { min: 1, max: 60 }); // s after which it ends itself (a spent dart on the ground still costs a script)

function setup() {
  state.t = null;
  for (const m of inbox) if (m.data && typeof m.data.x === 'number') state.t = m.data;
  state.at = time;
  state.born = time;
  state.y0 = self.pos.y;
  state.a0 = self.angle;
  state.armed = false;
  state.best = Infinity;
}

function steer(want, full) {
  let err = want - self.angle;
  while (err > Math.PI) err -= 2 * Math.PI;
  while (err < -Math.PI) err += 2 * Math.PI;
  // A gyro's spin is clockwise positive, the angle counterclockwise positive.
  set('heavygyro', 'spin', clamp(-(kp * err - kd * self.angVel), -1, 1));
  set('booster', 'throttle', Math.abs(err) < 0.9 ? full : 0.3);
}

function tick() {
  const t = state.t;
  if (!t) {
    // Knocked loose with no target: fly up and away from the base, unarmed.
    set('seeker', 'on', 0);
    steer(state.a0, 1);
    return;
  }
  const px = self.pos.x;
  const py = self.pos.y;
  if (py - state.y0 < climb && time - state.born < 1.5) {
    set('seeker', 'on', 0);
    steer(state.a0, 1);
    return;
  }
  // Where the target is now, by its last known point and speed (at most 12 s of guessing).
  const age = Math.min(time - state.at, 12);
  let tx = t.x + t.vx * age;
  let ty = t.y + t.vy * age;
  let dx = tx - px;
  let dy = ty - py;
  let dist = Math.sqrt(dx * dx + dy * dy);
  if (dist < state.best) state.best = dist;
  if (time - state.born > life || self.energy.stored < 25 || (state.best < 60 && dist > state.best + 120)) {
    set('heavywarhead', 'arm', 1);
    set('heavywarhead', 'detonate', 1);
    return;
  }
  const near = dist < look;
  set('seeker', 'on', near && !t.blind ? 1 : 0);
  if (near && !t.blind) {
    for (const c of contacts) {
      if (c.id !== t.id || c.side !== 'enemy') continue;
      const ex = c.pos.x - tx;
      const ey = c.pos.y - ty;
      if (ex * ex + ey * ey > trust * trust) break;
      t.x = c.pos.x;
      t.y = c.pos.y;
      t.vx = c.vel.x;
      t.vy = c.vel.y;
      state.at = time;
      tx = t.x;
      ty = t.y;
      dx = tx - px;
      dy = ty - py;
      dist = Math.sqrt(dx * dx + dy * dy);
      break;
    }
  }
  if (!state.armed && px > tx - t.l - armDist && px < tx + t.r + armDist && py > ty - t.d - armDist && py < ty + t.u + armDist) {
    set('heavywarhead', 'arm', 1);
    state.armed = true;
  }
  // Lead: aim where the target will be when the dart gets there.
  const rvx = self.vel.x - t.vx;
  const rvy = self.vel.y - t.vy;
  const closing = dist > 1e-6 ? (rvx * dx + rvy * dy) / dist : 0;
  const go = Math.min(dist / Math.max(closing, 60), 6);
  dx += t.vx * go;
  dy += t.vy * go;
  // A wide target: follow a path that runs level at `over` m above it and then down to it at a slope of `loft`,
  // by aiming at the point on that path `ahead` s of flight in front (a dart at full speed turns slowly, so it has to
  // start the bend early). Inside that distance it aims at the target itself.
  if (t.top) {
    const adx = Math.abs(dx);
    const reach = clamp(ahead * Math.sqrt(self.vel.x * self.vel.x + self.vel.y * self.vel.y), 60, 220);
    if (adx > reach) {
      dy += Math.min(loft * (adx - reach), over);
      dx = dx > 0 ? reach : -reach;
    }
  }
  const d = Math.sqrt(dx * dx + dy * dy) || 1;
  const ux = dx / d;
  const uy = dy / d;
  // Speed across the line (relative to the target), cancelled; a steady push along it; gravity held.
  const lat = rvx * -uy + rvy * ux;
  const fix = clamp(across * lat, -acrossMax, acrossMax);
  const ax = ux * push - fix * -uy;
  const ay = uy * push - fix * ux + 9.81;
  steer(Math.atan2(-ax, ay), 1);
}

